mat3 rotationMatrix(vec3 axis, float angle)
{
    axis = normalize(axis);
    float s = sin(angle);
    float c = cos(angle);
    float oc = 1.0 - c;

    return mat3(oc * axis.x * axis.x + c,           oc * axis.x * axis.y - axis.z * s,  oc * axis.z * axis.x + axis.y * s,
                oc * axis.x * axis.y + axis.z * s,  oc * axis.y * axis.y + c,           oc * axis.y * axis.z - axis.x * s,
                oc * axis.z * axis.x - axis.y * s,  oc * axis.y * axis.z + axis.x * s,  oc * axis.z * axis.z + c);
}


float sphereIntersectionTime(vec3 rayStart, vec3 rayDir, vec3 center, float radius){
    vec3 pos = rayStart - center;
    float a = dot(rayDir, rayDir);
    float b = 2.f * dot(pos, rayDir);
    float c = dot(pos, pos) - radius * radius;


    float temp = b * b - 4.f * a * c;
    if(temp < 0.f){
        return 1.f / 0.f;//This should be positive infinity
    }

    return (-b - sqrt(temp)) / (2.f * a);
}


void stepFunc(inout vec4 pos, inout vec4 dir, vec4 normal, float deltaTime){
    float magnitude = length(dir);
    normal = normalize(normal);
    dir -= dot(dir, normal) * normal;

    dir = normalize(dir) * magnitude;

    pos += dir * deltaTime;
}

vec4 normalFunc(vec4 pos, vec4 wormholePos, float innerRadius, float outerRadius){
    vec4 offset = pos - wormholePos;

    vec2 circlePos = vec2((outerRadius - length(offset.xyz)), offset.w * (outerRadius - innerRadius));//The sign of x is something to pay attention to

    vec2 circleNormal = normalize(circlePos);

    vec4 normal = normalize(vec4(-offset.xyz, 0)) * circleNormal.x + vec4(0,0,0,circleNormal.y);

    return normal;
}

bool processWormholeStep(inout vec4 rayPos, inout vec4 rayDir, vec3 p1, vec3 p2, float innerRadius, float outerRadius, float theta, float phi, float flip, float stepSize){
    vec4 offset1 = rayPos - vec4(p1, 0);
    vec4 offset2 = rayPos - vec4(p2, 0);

    if(length(offset1.xyz) <= outerRadius && length(offset2.xyz) <= outerRadius){
        //Invalid
        stepFunc(rayPos, rayDir, vec4(0,0,0,1), stepSize);
        return false;
    }

    vec4 p;
    vec4 otherP;
    vec4 offset;

    if(length(offset1.xyz) <= length(offset2.xyz)){
        p = vec4(p1, 0);
        offset = offset1;
        otherP = vec4(p2, 0);
    }else{
        p = vec4(p2, 0);
        offset = offset2;
        otherP = vec4(p1, 0);
        theta *= -1.f;
        phi *= -1.f;
    }

    vec4 normal = normalFunc(rayPos, p, innerRadius, outerRadius);


    stepFunc(rayPos, rayDir, normal, stepSize);
    if(rayPos.w < 0.f){
        //Go to the other wormhole side
        rayPos.w *= -1.f;
        rayDir.w *= -1.f;

        mat3 rot2 = rotationMatrix(vec3(0, 1, 0), phi) * rotationMatrix(vec3(0, 0, 1), theta);

        rayPos = (rayPos - p) + otherP;
        p = otherP;

        rayPos = vec4(flip * rot2 * (rayPos - p).xyz + p.xyz, rayPos.w);
        rayDir = vec4(flip * rot2 * rayDir.xyz, rayDir.w);
    }

    return length(rayPos.xyz - p.xyz) <= outerRadius;
}

//returns true if it ends outside the wormhole
bool processWormhole(inout vec4 rayPos, inout vec4 rayDir, vec3 p1, vec3 p2, float innerRadius, float outerRadius, float theta, float phi, float flip, int iterations, float stepSize){
   float t1 = sphereIntersectionTime(rayPos.xyz, rayDir.xyz, p1, outerRadius);
    float t2 = sphereIntersectionTime(rayPos.xyz, rayDir.xyz, p2, outerRadius);


    if(t1 < 0.f && length(rayPos.xyz - p1) < outerRadius){
        t1 = 0.0f;
    }
    if(t2 < 0.f && length(rayPos.xyz - p2) < outerRadius){
        t2 = 0.0f;
    }



    if(isinf(t1)){
        t1 = -1.f;
    }

    if(isinf(t2)){
        t2 = -1.f;
    }

    if(t1 >= 0.f && t2 >= 0.f){
        rayPos += rayDir * min(t1, t2);
    }else if(t1 >= 0.f){
        rayPos += rayDir * (t1 + 0.0);
    }else if(t2 >= 0.f){
        rayPos += rayDir * (t2 + 0.0);
    }else{
       return true;
    }

   for(int i = 0; i < iterations; i++){
       if(!processWormholeStep(rayPos, rayDir, p1, p2, innerRadius, outerRadius, theta, phi, flip, stepSize)){
           rayPos.w = 1.f;//w = 1 is the plane on which all objects lie when outside the wormhole.
           return true;
       }
   }

   return false;
}



void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv -= 0.5;
    uv.x *= iResolution.x / iResolution.y;


    //Camera Controls
    vec3 camPos = 5.f * vec3(cos(iTime * 0.5), sin(iTime * 0.5), 0);
    vec3 camDir = -camPos / length(camPos);

    //vec3 camPos = vec3(3, 2, 0);
    //vec3 camDir = vec3(-1,0,0);

    vec3 right = cross(camDir, vec3(0,0,1));
    right /= length(right);
    vec3 up = cross(right, camDir);
    up /= length(up);

    vec2 mouse = iMouse.xy / iResolution.xy - 0.5;

    vec4 rayPos = vec4(camPos, 1);
    vec4 rayDir = vec4(camDir + 2.f * (right * uv.x + up * uv.y) + (right * mouse.x + up * mouse.y), 0);
    rayDir /= length(rayDir);


    //Wormhole Controls
    vec3 p1 = vec3(0,2,0);
    vec3 p2 = vec3(0,-2,0);
    float outerRadius = 2.0f;
    float innerRadius = 1.f;
    float theta = 0.f;
    float phi = 0.f;
    bool flipChirality = false;
    int maxWormholing = 10;

    //this flips the angle phi on one end of the wormhole
    float flip = -1.f;
    if(flipChirality){
        flip = 1.f;
    }


    for(int i = 0; i < maxWormholing; i++){
        if(!processWormhole(rayPos, rayDir, p1, p2, innerRadius, outerRadius, theta, phi, flip, 60, 0.1)){
            break;
        }
    }


    vec3 sphere = vec3(4,4,3.f * cos(iTime));
    float sphereRadius = 1.f;
    float hi = sphereIntersectionTime(rayPos.xyz, rayDir.xyz, sphere, sphereRadius);

    if(!isinf(hi) && hi > 0.f){
        fragColor = vec4(normalize((rayPos.xyz + rayDir.xyz * hi) - sphere) * 0.5 + 0.5, 1);
        return;
    }

    // Output to screen


    vec3 temp = abs(rayDir.xyz);
    float maxDir = max(temp.x, max(temp.y, temp.z));
    vec3 color = 0.5 * (vec3(equal(vec3(maxDir), temp)) + vec3(equal(vec3(maxDir), rayDir.xyz)));

    //color = normalize(rayDir.xyz) * 0.5 + 0.5;//Pretty colors

    fragColor = vec4(color, 1);
}
